(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-trap-c5-advanced-1"]={"id":"unit22-trap-c5-advanced-1","unitId":"2-2","chapterIds":["2-2"],"unitType":"advanced","group":"선지 변형 유형 · 조건","name":"심화 5지선다 1","level":"심화","desc":"2-2단원 · 조건","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"조건","parts":[{"name":"U22-04 · 표현 방법의 적절성","items":[{"paragraphCount":1,"readingLabel":"교과서 49쪽 개념 발췌 정리","sourceLabel":"비판적 읽기와 다양한 읽기 방법 · 교과서 49쪽 개념 발췌 정리","passage":"[비판적 읽기와 다양한 읽기 방법 · 교과서 49쪽 개념 발췌 정리]\n비판적 읽기는 글의 내용과 필자의 생각을 무조건 수용하지 않고, 글에 제시된 내용이 올바른지 따져 가며 읽는 것이다. 내용의 타당성은 글에 나타난 주장이나 의견, 근거 등 글의 내용이 옳고 정확한지 살피는 기준이다. 관점의 공정성은 필자가 글의 내용을 한쪽으로 치우치지 않고 균형 있게 다루는지 판단하는 기준이다. 표현 방법의 적절성은 글의 목적과 내용에 비추어 표현 방법이 효과적이고 적절한지 평가하는 기준이다. 비판적 독자는 글에 반영된 사회·문화적 이념이 현재 우리의 상황에서 수용할 수 있는 것인지 판단한다. 창의적 읽기는 문제 상황을 비판적으로 이해하고 유연한 사고로 발상을 전환하며 새로운 대안을 탐구하는 읽기이다. 감상적 읽기는 글의 내용이나 필자의 생각에 공감하며 감동과 즐거움을 얻는 읽기이며, 서로 다른 감상을 공유하여 이해를 풍부하게 할 수 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["조건"],"id":"U22-04-S1","type":"mc","sent":"교과서 49쪽 개념 발췌 정리의 내용과 맞는 설명은?","options":["표현 방법의 적절성은 주장과 근거가 옳은지 보는 기준이다.","독자의 취향에만 맞으면 알맞은 표현이다.","표현이 새롭기만 하면 글의 목적에 맞는지는 따질 필요가 없다.","표현 방법의 적절성을 살필 때는 글의 목적과 내용을 먼저 생각한다. 글의 목적과 내용에 맞게 표현했는지 확인한다.","표현 방법이 효과적인지는 평가할 필요가 없다."],"answer":"표현 방법의 적절성을 살필 때는 글의 목적과 내용을 먼저 생각한다. 글의 목적과 내용에 맞게 표현했는지 확인한다.","why":"글을 쓴 목적과 전달하려는 내용을 생각해 보세요. 표현이 목적과 내용을 잘 전달하는 데 도움이 되는지 살피면 돼요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","choiceReviews":{"표현 방법의 적절성을 살필 때는 글의 목적과 내용을 먼저 생각한다. 글의 목적과 내용에 맞게 표현했는지 확인한다.":{"reason":"글을 쓴 목적과 전달하려는 내용을 생각해 보세요. 표현이 목적과 내용을 잘 전달하는 데 도움이 되는지 살피면 돼요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[]},"표현 방법의 적절성은 주장과 근거가 옳은지 보는 기준이다.":{"reason":"바르게 고치면: 내용의 타당성은 주장과 근거가 옳은지 보는 기준이다.\n글을 쓴 목적과 전달하려는 내용을 생각해 보세요. 표현이 목적과 내용을 잘 전달하는 데 도움이 되는지 살피면 돼요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":0,"end":12,"before":"표현 방법의 적절성은 ","after":"내용의 타당성은 "}]},"독자의 취향에만 맞으면 알맞은 표현이다.":{"reason":"바르게 고치면: 글의 목적과 내용에 맞아야 알맞은 표현이다.\n글을 쓴 목적과 전달하려는 내용을 생각해 보세요. 표현이 목적과 내용을 잘 전달하는 데 도움이 되는지 살피면 돼요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":0,"end":13,"before":"독자의 취향에만 맞으면 ","after":"글의 목적과 내용에 맞아야 "}]},"표현이 새롭기만 하면 글의 목적에 맞는지는 따질 필요가 없다.":{"reason":"바르게 고치면: 표현이 새로워도 글의 목적에 맞는지 따져야 한다.\n글을 쓴 목적과 전달하려는 내용을 생각해 보세요. 표현이 목적과 내용을 잘 전달하는 데 도움이 되는지 살피면 돼요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":4,"end":12,"before":"새롭기만 하면 ","after":"새로워도 "},{"start":19,"end":34,"before":"맞는지는 따질 필요가 없다.","after":"맞는지 따져야 한다."}]},"표현 방법이 효과적인지는 평가할 필요가 없다.":{"reason":"바르게 고치면: 표현 방법이 효과적인지 평가해야 한다.\n글을 쓴 목적과 전달하려는 내용을 생각해 보세요. 표현이 목적과 내용을 잘 전달하는 데 도움이 되는지 살피면 돼요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","edits":[{"start":7,"end":25,"before":"효과적인지는 평가할 필요가 없다.","after":"효과적인지 평가해야 한다."}]}},"pageSpecificReasons":true,"evidence":{"title":"표현 방법의 적절성","statement":"표현 방법의 적절성을 살필 때는 글의 목적과 내용을 먼저 생각한다. 글의 목적과 내용에 맞게 표현했는지 확인한다.","explanation":"글을 쓴 목적과 전달하려는 내용을 생각해 보세요. 표현이 목적과 내용을 잘 전달하는 데 도움이 되는지 살피면 돼요.\n교과서 49쪽 개념 발췌 정리에서 확인할 수 있어요.","valid":["D22:4"],"sources":[{"id":"D22","title":"비판적 읽기와 다양한 읽기 방법","label":"교과서 49쪽 개념 발췌 정리","sentences":[{"id":"D22:1","text":"비판적 읽기는 글의 내용과 필자의 생각을 무조건 수용하지 않고, 글에 제시된 내용이 올바른지 따져 가며 읽는 것이다.","paragraph":0,"memberIds":["D22:1"],"topic":"비판적 읽기"},{"id":"D22:2","text":"내용의 타당성은 글에 나타난 주장이나 의견, 근거 등 글의 내용이 옳고 정확한지 살피는 기준이다.","paragraph":0,"memberIds":["D22:2"],"topic":"내용의 타당성"},{"id":"D22:3","text":"관점의 공정성은 필자가 글의 내용을 한쪽으로 치우치지 않고 균형 있게 다루는지 판단하는 기준이다.","paragraph":0,"memberIds":["D22:3"],"topic":"관점의 공정성"},{"id":"D22:4","text":"표현 방법의 적절성은 글의 목적과 내용에 비추어 표현 방법이 효과적이고 적절한지 평가하는 기준이다.","paragraph":0,"memberIds":["D22:4"],"topic":"표현 방법의 적절성"},{"id":"D22:5","text":"비판적 독자는 글에 반영된 사회·문화적 이념이 현재 우리의 상황에서 수용할 수 있는 것인지 판단한다.","paragraph":0,"memberIds":["D22:5"],"topic":"사회·문화적 이념"},{"id":"D22:6","text":"창의적 읽기는 문제 상황을 비판적으로 이해하고 유연한 사고로 발상을 전환하며 새로운 대안을 탐구하는 읽기이다.","paragraph":0,"memberIds":["D22:6"],"topic":"창의적 읽기"},{"id":"D22:7","text":"감상적 읽기는 글의 내용이나 필자의 생각에 공감하며 감동과 즐거움을 얻는 읽기이며, 서로 다른 감상을 공유하여 이해를 풍부하게 할 수 있다.","paragraph":0,"memberIds":["D22:7"],"topic":"감상적 읽기"}]}]},"editorSourceVersion":"eeee325b6dc6b992e07c8e51ae3355055b1fba90b5d0fe4b53ad338744d94013"}]},{"name":"U22-11 · 퍼블릭 시어터의 사명","items":[{"paragraphCount":1,"readingLabel":"3문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 3문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 3문단]\n극장 측은 “공원에서 이루어지는 줄 서기 대리 행위는 셰익스피어 정신에 어긋난다.”라고 주장하면서 대리로 줄을 서 주는 사람들의 영업을 막기 위해 노력했다. 국가 보조금을 받는 비영리 사업체인 퍼블릭 시어터의 사명은 모든 계층의 시민이 훌륭한 극장 시설을 이용할 수 있게 하는 것이다. 당시 뉴욕 검찰 총장이었던 앤드루 쿠오모(Andrew Cuomo)는 온라인 사이트에 압력을 가해 대리 줄 서기로 입장권을 구해 준다는 광고를 중단하게 했다. 그러면서 그는 이렇게 강조했다. “무료여야 하는 입장권을 판매하는 행위는 기관이 납세자의 후원을 받아 제공하는 혜택을 누릴 뉴요커의 권리를 침해한다.” 사람을 고용해 대리로 줄을 세우거나 암표를 파는 행동이 잘못일까?","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["조건"],"id":"U22-11-S1","type":"mc","sent":"3문단의 내용과 맞는 설명은?","options":["퍼블릭 시어터는 정부 지원금을 받는다. 돈을 버는 것을 목표로 하지 않으며, 모든 시민에게 좋은 극장 시설을 제공하려 한다.","퍼블릭 시어터는 돈을 버는 것을 가장 큰 목표로 삼는다.","퍼블릭 시어터는 비싼 표를 산 시민만 시설을 이용하게 하려 한다.","퍼블릭 시어터는 정부 지원금 없이 암표 수익만으로 운영된다.","퍼블릭 시어터는 시민들이 시설을 이용하지 못하게 하려 한다."],"answer":"퍼블릭 시어터는 정부 지원금을 받는다. 돈을 버는 것을 목표로 하지 않으며, 모든 시민에게 좋은 극장 시설을 제공하려 한다.","why":"극장이 세운 목표는 돈을 많이 버는 일이 아니에요. 가난하든 부유하든 시민들이 좋은 극장 시설을 누리게 하려는 것이에요.\n3문단에서 확인할 수 있어요.","choiceReviews":{"퍼블릭 시어터는 정부 지원금을 받는다. 돈을 버는 것을 목표로 하지 않으며, 모든 시민에게 좋은 극장 시설을 제공하려 한다.":{"reason":"극장이 세운 목표는 돈을 많이 버는 일이 아니에요. 가난하든 부유하든 시민들이 좋은 극장 시설을 누리게 하려는 것이에요.\n3문단에서 확인할 수 있어요.","edits":[]},"퍼블릭 시어터는 돈을 버는 것을 가장 큰 목표로 삼는다.":{"reason":"바르게 고치면: 퍼블릭 시어터는 돈을 버는 것을 목표로 하지 않는다.\n극장이 세운 목표는 돈을 많이 버는 일이 아니에요. 가난하든 부유하든 시민들이 좋은 극장 시설을 누리게 하려는 것이에요.\n3문단에서 확인할 수 있어요.","edits":[{"start":18,"end":23,"before":"가장 큰 ","after":""},{"start":27,"end":31,"before":"삼는다.","after":"하지 않는다."}]},"퍼블릭 시어터는 비싼 표를 산 시민만 시설을 이용하게 하려 한다.":{"reason":"바르게 고치면: 퍼블릭 시어터는 모든 시민이 시설을 이용하게 하려 한다.\n극장이 세운 목표는 돈을 많이 버는 일이 아니에요. 가난하든 부유하든 시민들이 좋은 극장 시설을 누리게 하려는 것이에요.\n3문단에서 확인할 수 있어요.","edits":[{"start":9,"end":21,"before":"비싼 표를 산 시민만 ","after":"모든 시민이 "}]},"퍼블릭 시어터는 정부 지원금 없이 암표 수익만으로 운영된다.":{"reason":"바르게 고치면: 퍼블릭 시어터는 정부 지원금을 받는다.\n극장이 세운 목표는 돈을 많이 버는 일이 아니에요. 가난하든 부유하든 시민들이 좋은 극장 시설을 누리게 하려는 것이에요.\n3문단에서 확인할 수 있어요.","edits":[{"start":12,"end":33,"before":"지원금 없이 암표 수익만으로 운영된다.","after":"지원금을 받는다."}]},"퍼블릭 시어터는 시민들이 시설을 이용하지 못하게 하려 한다.":{"reason":"바르게 고치면: 퍼블릭 시어터는 시민들이 시설을 이용하게 하려 한다.\n극장이 세운 목표는 돈을 많이 버는 일이 아니에요. 가난하든 부유하든 시민들이 좋은 극장 시설을 누리게 하려는 것이에요.\n3문단에서 확인할 수 있어요.","edits":[{"start":18,"end":27,"before":"이용하지 못하게 ","after":"이용하게 "}]}},"pageSpecificReasons":true,"evidence":{"title":"퍼블릭 시어터의 사명","statement":"퍼블릭 시어터는 정부 지원금을 받는다. 돈을 버는 것을 목표로 하지 않으며, 모든 시민에게 좋은 극장 시설을 제공하려 한다.","explanation":"극장이 세운 목표는 돈을 많이 버는 일이 아니에요. 가난하든 부유하든 시민들이 좋은 극장 시설을 누리게 하려는 것이에요.\n3문단에서 확인할 수 있어요.","valid":["L03:2"],"sources":[{"id":"L03","title":"줄 서기를 돈으로 살 수 있을까","label":"3문단","sentences":[{"id":"L03:1","text":"극장 측은 “공원에서 이루어지는 줄 서기 대리 행위는 셰익스피어 정신에 어긋난다.”라고 주장하면서 대리로 줄을 서 주는 사람들의 영업을 막기 위해 노력했다.","paragraph":0,"memberIds":["L03:1"],"topic":"극장은 \"대신 줄 서 주는 건 셰익스피어 정신(이 공연의 정신)과 맞지 않는다.\"라고 말했다. 그리고 그 사업을 막으려고 애썼다."},{"id":"L03:2","text":"국가 보조금을 받는 비영리 사업체인 퍼블릭 시어터의 사명은 모든 계층의 시민이 훌륭한 극장 시설을 이용할 수 있게 하는 것이다.","paragraph":0,"memberIds":["L03:2"],"topic":"이 극장은 돈을 벌려고 만든 곳이 아니다(비영리). 나라가 세금으로 돈도 대 준다(보조금). 극장이 꼭 해야 할 일(사명)은 부자든 아니든 모든 시민이 좋은 공연을 보게 하는 것이다."},{"id":"L03:3","text":"당시 뉴욕 검찰 총장이었던 앤드루 쿠오모(Andrew Cuomo)는 온라인 사이트에 압력을 가해 대리 줄 서기로 입장권을 구해 준다는 광고를 중단하게 했다.","paragraph":0,"memberIds":["L03:3"],"topic":"뉴욕 검찰 총장 쿠오모도 나섰다. 인터넷 사이트를 압박해서 그 광고를 내리게 했다."},{"id":"L03:4","text":"그러면서 그는 이렇게 강조했다.","paragraph":0,"memberIds":["L03:4"],"topic":"그리고 이렇게 말했다."},{"id":"L03:5","text":"“무료여야 하는 입장권을 판매하는 행위는 기관이 납세자의 후원을 받아 제공하는 혜택을 누릴 뉴요커의 권리를 침해한다.”","paragraph":0,"memberIds":["L03:5"],"topic":"\"이 공연은 시민이 낸 세금의 도움으로 여는 혜택이다. 그러니 뉴욕 시민 누구나 누릴 권리가 있다. 공짜여야 할 표를 파는 건 그 권리를 빼앗는(침해하는) 일이다.\""},{"id":"L03:6","text":"사람을 고용해 대리로 줄을 세우거나 암표를 파는 행동이 잘못일까?","paragraph":0,"memberIds":["L03:6"],"topic":"그렇다면 돈을 주고 사람을 시켜 대신 줄을 세우거나, 표를 비싸게 되파는(암표) 건 정말 잘못일까?"}]}]},"editorSourceVersion":"f5863a9dd99f01f3704b800f983414100da3579aec6ba73cc75bcad56ccdb949"}]},{"name":"U22-15 · 거래 자유의 조건","items":[{"paragraphCount":1,"readingLabel":"4문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 4문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 4문단]\n줄 서기에 관해 시장을 옹호하는 입장에는 두 가지 주장이 있다. 하나는 개인의 자유 존중에 대한 것이고, 다른 하나는 행복이나 사회적 효용의 극대화에 대한 주장이다. 첫 번째는 자유 지상주의자의 입장이다. 그들은 타인의 권리를 침범하지 않는 한 원하는 재화는 무엇이든 자유롭게 사고팔 수 있어야 한다고 주장한다. 자유 지상주의자는 장기 매매 금지법에 반대하는 것과 같은 이유로 암표 매매 금지법에 반대한다. 이러한 법은 성인이 상호 동의에 따라 내린 선택을 방해함으로써 개인의 자유를 침해한다고 믿기 때문이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["조건"],"id":"U22-15-S1","type":"mc","sent":"4문단의 내용과 맞는 설명은?","options":["두 사람이 동의하면 다른 사람의 권리를 해쳐도 거래할 수 있다.","거래하는 사람이 돈을 잃지 않는다면 다른 사람의 권리를 해쳐도 된다.","다른 사람의 권리를 해치지 않아도 자유로운 거래를 막아야 한다.","다른 사람의 권리를 해치지 않아도 두 사람의 재산이 같을 때만 거래할 수 있다.","자유 지상주의자는 자유로운 거래를 지지한다. 다만 다른 사람의 권리를 해쳐서는 안 된다."],"answer":"자유 지상주의자는 자유로운 거래를 지지한다. 다만 다른 사람의 권리를 해쳐서는 안 된다.","why":"자유 지상주의자도 모든 거래를 허용하는 것은 아니에요. 물건을 사고팔 때 다른 사람의 권리를 해치지 않아야 해요.\n4문단에서 확인할 수 있어요.","choiceReviews":{"자유 지상주의자는 자유로운 거래를 지지한다. 다만 다른 사람의 권리를 해쳐서는 안 된다.":{"reason":"자유 지상주의자도 모든 거래를 허용하는 것은 아니에요. 물건을 사고팔 때 다른 사람의 권리를 해치지 않아야 해요.\n4문단에서 확인할 수 있어요.","edits":[]},"두 사람이 동의하면 다른 사람의 권리를 해쳐도 거래할 수 있다.":{"reason":"바르게 고치면: 두 사람이 동의해도 다른 사람의 권리를 해쳐서는 안 된다.\n자유 지상주의자도 모든 거래를 허용하는 것은 아니에요. 물건을 사고팔 때 다른 사람의 권리를 해치지 않아야 해요.\n4문단에서 확인할 수 있어요.","edits":[{"start":6,"end":11,"before":"동의하면 ","after":"동의해도 "},{"start":22,"end":35,"before":"해쳐도 거래할 수 있다.","after":"해쳐서는 안 된다."}]},"거래하는 사람이 돈을 잃지 않는다면 다른 사람의 권리를 해쳐도 된다.":{"reason":"바르게 고치면: 거래하는 사람이 돈을 잃지 않더라도 다른 사람의 권리를 해쳐서는 안 된다.\n자유 지상주의자도 모든 거래를 허용하는 것은 아니에요. 물건을 사고팔 때 다른 사람의 권리를 해치지 않아야 해요.\n4문단에서 확인할 수 있어요.","edits":[{"start":15,"end":20,"before":"않는다면 ","after":"않더라도 "},{"start":31,"end":35,"before":"해쳐도 ","after":"해쳐서는 안 "}]},"다른 사람의 권리를 해치지 않아도 자유로운 거래를 막아야 한다.":{"reason":"바르게 고치면: 다른 사람의 권리를 해치지 않는다면 자유롭게 거래할 수 있어야 한다.\n자유 지상주의자도 모든 거래를 허용하는 것은 아니에요. 물건을 사고팔 때 다른 사람의 권리를 해치지 않아야 해요.\n4문단에서 확인할 수 있어요.","edits":[{"start":15,"end":32,"before":"않아도 자유로운 거래를 막아야 ","after":"않는다면 자유롭게 거래할 수 있어야 "}]},"다른 사람의 권리를 해치지 않아도 두 사람의 재산이 같을 때만 거래할 수 있다.":{"reason":"바르게 고치면: 다른 사람의 권리를 해치지 않는다면 두 사람의 재산이 달라도 거래할 수 있다.\n자유 지상주의자도 모든 거래를 허용하는 것은 아니에요. 물건을 사고팔 때 다른 사람의 권리를 해치지 않아야 해요.\n4문단에서 확인할 수 있어요.","edits":[{"start":15,"end":19,"before":"않아도 ","after":"않는다면 "},{"start":29,"end":35,"before":"같을 때만 ","after":"달라도 "}]}},"pageSpecificReasons":true,"evidence":{"title":"거래 자유의 조건","statement":"자유 지상주의자는 자유로운 거래를 지지한다. 다만 다른 사람의 권리를 해쳐서는 안 된다.","explanation":"자유 지상주의자도 모든 거래를 허용하는 것은 아니에요. 물건을 사고팔 때 다른 사람의 권리를 해치지 않아야 해요.\n4문단에서 확인할 수 있어요.","valid":["L04:4"],"sources":[{"id":"L04","title":"줄 서기를 돈으로 살 수 있을까","label":"4문단","sentences":[{"id":"L04:1","text":"줄 서기에 관해 시장을 옹호하는 입장에는 두 가지 주장이 있다.","paragraph":0,"memberIds":["L04:1"],"topic":"돈으로 줄을 사는 것(시장)에 찬성하는 쪽의 이유는 두 가지다."},{"id":"L04:2","text":"하나는 개인의 자유 존중에 대한 것이고, 다른 하나는 행복이나 사회적 효용의 극대화에 대한 주장이다.","paragraph":0,"memberIds":["L04:2"],"topic":"첫째는 '개인의 자유를 존중하자'는 것이다. 둘째는 '사람들의 만족(효용)을 가장 크게 만들자'는 것이다."},{"id":"L04:3","text":"첫 번째는 자유 지상주의자의 입장이다.","paragraph":0,"memberIds":["L04:3"],"topic":"첫째 이유는 '자유 지상주의자'의 생각이다. 개인의 자유를 무엇보다 중요하게 여기는 사람들이다."},{"id":"L04:4","text":"그들은 타인의 권리를 침범하지 않는 한 원하는 재화는 무엇이든 자유롭게 사고팔 수 있어야 한다고 주장한다.","paragraph":0,"memberIds":["L04:4"],"topic":"그들은 이렇게 말한다. \"남의 권리를 침범하지(피해를 주지) 않는 한, 무엇이든 자유롭게 사고팔 수 있어야 한다.\""},{"id":"L04:5","text":"자유 지상주의자는 장기 매매 금지법에 반대하는 것과 같은 이유로 암표 매매 금지법에 반대한다.","paragraph":0,"memberIds":["L04:5"],"topic":"그래서 그들은 '암표를 팔지 마라'는 법에 반대한다. '장기를 사고팔지 마라'는 법에 반대하는 것과 같은 이유에서다."},{"id":"L04:6","text":"이러한 법은 성인이 상호 동의에 따라 내린 선택을 방해함으로써 개인의 자유를 침해한다고 믿기 때문이다.","paragraph":0,"memberIds":["L04:6"],"topic":"어른 둘이 서로 좋다고 합의한 거래를 법이 막으면, 개인의 자유를 빼앗는 것이라고 믿기 때문이다."}]}]},"editorSourceVersion":"d1c30d76a35416b9e8cd446a94358dfd856cb00d01ad398d23b429b1690812c0"}]},{"name":"U22-23 · 조건을 전제로 한 암표 거래 평가","items":[{"paragraphCount":1,"readingLabel":"8문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 8문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 8문단]\n자유 시장을 옹호하는 주장이 맞는다면, 줄 서기의 본질을 침범했다는 이유로 암표상과 대리 줄 서기를 비난해서는 안 된다. 오히려 가격이 낮게 책정된 재화를 가장 많은 대가를 지불하려는 사람에게 돌아가게 만들어 사회적 효용을 증가시킨 공로로 칭찬해야 마땅하다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["조건"],"id":"U22-23-S1","type":"mc","sent":"8문단의 내용과 맞는 설명은?","options":["8문단은 아무 조건 없이 암표상을 칭찬해야 한다고 말한다.","8문단은 자유 시장을 지지하는 주장이 맞다면 암표상을 비난해야 한다고 말한다.","8문단에서는 자유 시장을 지지하는 주장이 맞다고 가정한다. 이 주장이 맞다면 암표상과 대리 줄 서기를 칭찬해야 한다고 말한다.","8문단은 자유 시장에 반대하는 주장이 맞다고 가정한다.","자유 시장을 지지하는 주장이 맞아도 대리 줄 서기는 칭찬하면 안 된다고 말한다."],"answer":"8문단에서는 자유 시장을 지지하는 주장이 맞다고 가정한다. 이 주장이 맞다면 암표상과 대리 줄 서기를 칭찬해야 한다고 말한다.","why":"“맞는다면”이라는 가정이 붙어 있어요. 필자는 시장 옹호 주장을 받아들일 경우 암표상을 칭찬해야 한다는 결론이 나온다고 설명합니다. 조건 없이 암표상에 찬성한 말은 아니에요.\n8문단에서 확인할 수 있어요.","choiceReviews":{"8문단에서는 자유 시장을 지지하는 주장이 맞다고 가정한다. 이 주장이 맞다면 암표상과 대리 줄 서기를 칭찬해야 한다고 말한다.":{"reason":"“맞는다면”이라는 가정이 붙어 있어요. 필자는 시장 옹호 주장을 받아들일 경우 암표상을 칭찬해야 한다는 결론이 나온다고 설명합니다. 조건 없이 암표상에 찬성한 말은 아니에요.\n8문단에서 확인할 수 있어요.","edits":[]},"8문단은 아무 조건 없이 암표상을 칭찬해야 한다고 말한다.":{"reason":"바르게 고치면: 8문단은 자유 시장을 지지하는 주장이 맞다면 암표상을 칭찬해야 한다고 말한다.\n“맞는다면”이라는 가정이 붙어 있어요. 필자는 시장 옹호 주장을 받아들일 경우 암표상을 칭찬해야 한다는 결론이 나온다고 설명합니다. 조건 없이 암표상에 찬성한 말은 아니에요.\n8문단에서 확인할 수 있어요.","edits":[{"start":5,"end":14,"before":"아무 조건 없이 ","after":"자유 시장을 지지하는 주장이 맞다면 "}]},"8문단은 자유 시장을 지지하는 주장이 맞다면 암표상을 비난해야 한다고 말한다.":{"reason":"바르게 고치면: 8문단은 자유 시장을 지지하는 주장이 맞다면 암표상을 칭찬해야 한다고 말한다.\n“맞는다면”이라는 가정이 붙어 있어요. 필자는 시장 옹호 주장을 받아들일 경우 암표상을 칭찬해야 한다는 결론이 나온다고 설명합니다. 조건 없이 암표상에 찬성한 말은 아니에요.\n8문단에서 확인할 수 있어요.","edits":[{"start":30,"end":35,"before":"비난해야 ","after":"칭찬해야 "}]},"8문단은 자유 시장에 반대하는 주장이 맞다고 가정한다.":{"reason":"바르게 고치면: 8문단은 자유 시장을 지지하는 주장이 맞다고 가정한다.\n“맞는다면”이라는 가정이 붙어 있어요. 필자는 시장 옹호 주장을 받아들일 경우 암표상을 칭찬해야 한다는 결론이 나온다고 설명합니다. 조건 없이 암표상에 찬성한 말은 아니에요.\n8문단에서 확인할 수 있어요.","edits":[{"start":8,"end":17,"before":"시장에 반대하는 ","after":"시장을 지지하는 "}]},"자유 시장을 지지하는 주장이 맞아도 대리 줄 서기는 칭찬하면 안 된다고 말한다.":{"reason":"바르게 고치면: 자유 시장을 지지하는 주장이 맞다면 대리 줄 서기를 칭찬해야 한다고 말한다.\n“맞는다면”이라는 가정이 붙어 있어요. 필자는 시장 옹호 주장을 받아들일 경우 암표상을 칭찬해야 한다는 결론이 나온다고 설명합니다. 조건 없이 암표상에 찬성한 말은 아니에요.\n8문단에서 확인할 수 있어요.","edits":[{"start":16,"end":20,"before":"맞아도 ","after":"맞다면 "},{"start":25,"end":40,"before":"서기는 칭찬하면 안 된다고 ","after":"서기를 칭찬해야 한다고 "}]}},"pageSpecificReasons":true,"evidence":{"title":"조건을 전제로 한 암표 거래 평가","statement":"8문단에서는 자유 시장을 지지하는 주장이 맞다고 가정한다. 이 주장이 맞다면 암표상과 대리 줄 서기를 칭찬해야 한다고 말한다.","explanation":"“맞는다면”이라는 가정이 붙어 있어요. 필자는 시장 옹호 주장을 받아들일 경우 암표상을 칭찬해야 한다는 결론이 나온다고 설명합니다. 조건 없이 암표상에 찬성한 말은 아니에요.\n8문단에서 확인할 수 있어요.","valid":["L08:1"],"sources":[{"id":"L08","title":"줄 서기를 돈으로 살 수 있을까","label":"8문단","sentences":[{"id":"L08:1","text":"자유 시장을 옹호하는 주장이 맞는다면, 줄 서기의 본질을 침범했다는 이유로 암표상과 대리 줄 서기를 비난해서는 안 된다.","paragraph":0,"memberIds":["L08:1"],"topic":"시장 편 주장이 맞다고 해 보자. 그러면 \"줄 서기를 망쳤다(줄 서기의 본질을 침범했다)\"며 암표상과 대리 줄 서기를 욕하면(비난하면) 안 된다."},{"id":"L08:2","text":"오히려 가격이 낮게 책정된 재화를 가장 많은 대가를 지불하려는 사람에게 돌아가게 만들어 사회적 효용을 증가시킨 공로로 칭찬해야 마땅하다.","paragraph":0,"memberIds":["L08:2"],"topic":"앞의 가정이 맞다면 오히려 칭찬해야 한다는 결론이 나온다. 가장 많은 돈을 내려는 사람에게 표를 보내 사회 전체의 만족을 키웠다는 이유다. 필자가 조건 없이 칭찬하는 말은 아니다."}]}]},"editorSourceVersion":"92717876ec0d7d3cc6604ae1a43fb005871cd4178a5a1addb0b0deea00d83694"}]},{"name":"U22-43 · 한정된 좌석과 평등한 관람 취지","items":[{"paragraphCount":1,"readingLabel":"18문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 18문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 18문단]\n퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다. 말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다. 물론 좌석 수는 한정되어 있다. 정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다. 하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다. 본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다. 이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["조건"],"id":"U22-43-S1","type":"mc","sent":"18문단의 내용과 맞는 설명은?","options":["모든 시민이 동시에 공연을 볼 수 있을 만큼 좌석이 있다.","공연의 목적은 돈을 얼마나 낼 수 있는지에 따라 볼 기회를 주는 것이다.","좌석이 부족해 모든 시민이 동시에 공연을 볼 수는 없다. 그래도 돈이 많든 적든 누구나 무료 공연을 볼 기회를 똑같이 주려는 것이다.","무료 공연은 비싼 값을 내는 순서대로 보게 하려는 공연이다.","무료 공연은 돈 많은 사람부터 보게 하려는 공연이다."],"answer":"좌석이 부족해 모든 시민이 동시에 공연을 볼 수는 없다. 그래도 돈이 많든 적든 누구나 무료 공연을 볼 기회를 똑같이 주려는 것이다.","why":"좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","choiceReviews":{"좌석이 부족해 모든 시민이 동시에 공연을 볼 수는 없다. 그래도 돈이 많든 적든 누구나 무료 공연을 볼 기회를 똑같이 주려는 것이다.":{"reason":"좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","edits":[]},"모든 시민이 동시에 공연을 볼 수 있을 만큼 좌석이 있다.":{"reason":"바르게 고치면: 좌석이 부족해 모든 시민이 동시에 공연을 볼 수는 없다.\n좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","edits":[{"start":0,"end":3,"before":"모든 ","after":"좌석이 부족해 모든 "},{"start":17,"end":32,"before":"수 있을 만큼 좌석이 있다.","after":"수는 없다."}]},"공연의 목적은 돈을 얼마나 낼 수 있는지에 따라 볼 기회를 주는 것이다.":{"reason":"바르게 고치면: 공연의 목적은 돈을 얼마나 낼 수 있는지와 상관없이 볼 기회를 주는 것이다.\n좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","edits":[{"start":19,"end":27,"before":"있는지에 따라 ","after":"있는지와 상관없이 "}]},"무료 공연은 비싼 값을 내는 순서대로 보게 하려는 공연이다.":{"reason":"바르게 고치면: 무료 공연은 누구에게나 볼 기회를 똑같이 주려는 공연이다.\n좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","edits":[{"start":7,"end":28,"before":"비싼 값을 내는 순서대로 보게 하려는 ","after":"누구에게나 볼 기회를 똑같이 주려는 "}]},"무료 공연은 돈 많은 사람부터 보게 하려는 공연이다.":{"reason":"바르게 고치면: 무료 공연은 돈이 많든 적든 똑같이 볼 기회를 주려는 공연이다.\n좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","edits":[{"start":7,"end":24,"before":"돈 많은 사람부터 보게 하려는 ","after":"돈이 많든 적든 똑같이 볼 기회를 주려는 "}]}},"pageSpecificReasons":true,"evidence":{"title":"한정된 좌석과 평등한 관람 취지","statement":"좌석이 부족해 모든 시민이 동시에 공연을 볼 수는 없다. 그래도 돈이 많든 적든 누구나 무료 공연을 볼 기회를 똑같이 주려는 것이다.","explanation":"좌석 수가 정해져 있으므로 모든 시민이 한꺼번에 볼 수는 없어요. 하지만 돈을 얼마나 낼 수 있는지에 따라 기회를 다르게 주려는 공연은 아니에요.\n18문단에서 확인할 수 있어요.","valid":["L18:3","L18:4","L18:5"],"sources":[{"id":"L18","title":"줄 서기를 돈으로 살 수 있을까","label":"18문단","sentences":[{"id":"L18:1","text":"퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다.","paragraph":0,"memberIds":["L18:1"],"topic":"극장은 이 무료 공연을 모두의 축제, 시민들의 잔치로 여긴다."},{"id":"L18:2","text":"말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다.","paragraph":0,"memberIds":["L18:2"],"topic":"말하자면 도시가 시민들, 곧 자기 자신에게 주는 선물이다."},{"id":"L18:3","text":"물론 좌석 수는 한정되어 있다.","paragraph":0,"memberIds":["L18:3"],"topic":"물론 자리는 정해져 있다."},{"id":"L18:4","text":"정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다.","paragraph":0,"memberIds":["L18:4"],"topic":"그날 저녁에 모든 시민이 다 올 수는 없으니까."},{"id":"L18:5","text":"하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다.","paragraph":0,"memberIds":["L18:5"],"topic":"하지만 극장이 원래 하려던 것(취지)은 돈이 있든 없든 누구나 똑같이 공짜로 공연을 보게 하는 것이다."},{"id":"L18:6","text":"본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다.","paragraph":0,"memberIds":["L18:6"],"topic":"원래 선물이어야 할 행사에서 입장료를 받거나 암표상이 돈을 벌게 놔두면, 그 목적과 어긋난다."},{"id":"L18:7","text":"이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","paragraph":0,"memberIds":["L18:7"],"topic":"그건 모두의 축제를 개인의 돈벌이 수단(사적 이익의 도구)으로 바꿔 버리는 일이다."}]}]},"editorSourceVersion":"33fa6896915088d55159cb11f7e4a8a7a1afaae0dcee801bcc786945906fcebc"}]}]};})(window);
